package kr.memorynotes;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class BackupValidationTest {
 JSONObject snapshot()throws Exception{return new JSONObject("{\"version\":1,\"subjects\":[{\"id\":\"s\",\"name\":\"공조냉동\"}],\"chapters\":[],\"notes\":[],\"history\":[]}");}
 JSONObject addNote(JSONObject s)throws Exception{Note n=new Note();n.title="표면적 <>& 한글";n.subject="s";n.body="공식 {{πdL}}\n"+"긴 내용".repeat(1000);JSONObject row=new JSONObject();row.put("id",n.id);row.put("data",n.json().toString());s.getJSONArray("notes").put(row);return row;}
 @Test public void validSnapshot()throws Exception{JSONObject s=snapshot();addNote(s);BackupManager.validate(s,Set.of("notes.json"));}
 @Test public void longKoreanRoundTrip()throws Exception{Note n=new Note();n.title="<>& 한글";n.body="암기공식\n".repeat(2000);n.tags="공식,π,℃";Note copy=Note.from(new JSONObject(n.json().toString()));assertEquals(n.body,copy.body);assertEquals(n.tags,copy.tags);assertEquals(n.title,copy.title);}
 @Test public void rejectsMissingPhoto()throws Exception{JSONObject s=snapshot(),row=addNote(s);Note n=Note.from(new JSONObject(row.getString("data")));n.images.put(new JSONObject("{\"file\":\"missing.img\",\"masks\":[]}"));row.put("data",n.json().toString());assertThrows(Exception.class,()->BackupManager.validate(s,Set.of("notes.json")));}
 @Test public void rejectsUnsupportedVersion()throws Exception{JSONObject s=snapshot();s.put("version",2);assertThrows(Exception.class,()->BackupManager.validate(s,Set.of("notes.json")));}
 @Test public void rejectsForeignChapter()throws Exception{JSONObject s=snapshot(),r=addNote(s);Note n=Note.from(new JSONObject(r.getString("data")));n.chapter="missing";r.put("data",n.json().toString());assertThrows(Exception.class,()->BackupManager.validate(s,Set.of("notes.json")));}
 @Test public void rejectsDuplicateNotes()throws Exception{JSONObject s=snapshot();JSONObject r=addNote(s);s.getJSONArray("notes").put(r);assertThrows(Exception.class,()->BackupManager.validate(s,Set.of("notes.json")));}
 @Test public void rejectsInvalidMask()throws Exception{JSONObject s=snapshot(),r=addNote(s);Note n=Note.from(new JSONObject(r.getString("data")));n.images.put(new JSONObject("{\"file\":\"x.img\",\"masks\":[[0,0,1.1,1]]}"));r.put("data",n.json().toString());assertThrows(Exception.class,()->BackupManager.validate(s,Set.of("notes.json","images/x.img")));}
 @Test public void rejectsUnknownDatabaseColumns()throws Exception{JSONObject s=snapshot();s.getJSONArray("subjects").getJSONObject(0).put("unsafe","x");assertThrows(Exception.class,()->BackupManager.validate(s,Set.of("notes.json")));}
 @Test public void rejectsMissingTables()throws Exception{JSONObject s=snapshot();s.remove("notes");assertThrows(Exception.class,()->BackupManager.validate(s,Set.of("notes.json")));}
 @Test public void allowsRenamedSubjectWithStableId()throws Exception{JSONObject s=snapshot();addNote(s);s.getJSONArray("subjects").getJSONObject(0).put("name","새 과목명");BackupManager.validate(s,Set.of("notes.json"));}
 @Test public void rejectsInvalidHistoryDate()throws Exception{JSONObject s=snapshot();JSONObject n=addNote(s);JSONObject h=new JSONObject();h.put("id",1);h.put("note",n.getString("id"));h.put("day","2026-02-30");h.put("rating",0);s.getJSONArray("history").put(h);assertThrows(Exception.class,()->BackupManager.validate(s,Set.of("notes.json")));}
 @Test public void rejectsIncompleteNoteSchema()throws Exception{JSONObject s=snapshot(),r=addNote(s);JSONObject n=new JSONObject(r.getString("data"));n.remove("body");r.put("data",n.toString());assertThrows(Exception.class,()->BackupManager.validate(s,Set.of("notes.json")));}
 @Test public void rejectsWrongFieldTypes()throws Exception{JSONObject s=snapshot(),r=addNote(s);JSONObject n=new JSONObject(r.getString("data"));n.put("favorite","true");r.put("data",n.toString());assertThrows(Exception.class,()->BackupManager.validate(s,Set.of("notes.json")));}
 @Test public void exportAndRestoreShareLimits()throws Exception{BackupManager.checkExportLimits(100,100,2);assertThrows(Exception.class,()->BackupManager.checkExportLimits(BackupManager.MAX_META+1,0,1));assertThrows(Exception.class,()->BackupManager.checkExportLimits(100,BackupManager.MAX_TOTAL,2));assertThrows(Exception.class,()->BackupManager.checkExportLimits(100,0,10001));}
}
